INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 5, 'theory', 'Quiz: the scheduler and EEVDF');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 5, 0, 'Which algorithm replaced CFS in the kernel starting with version 6.6?', '["The O(1) scheduler", "EEVDF", "Round Robin", "BFS/MuQSS"]', 1, 'EEVDF adds the notions of lag-based eligibility and a virtual deadline, and lets a task ask for a short slice for better latency.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 5, 1, 'Two ready tasks have nice 0 (weight 1024) and nice 5 (weight 335). Roughly how will they split the CPU?', '["Equally", "Five to one", "One to three", "Roughly three to one"]', 3, 'Shares are proportional to weights: 1024 to 335 is a bit more than three. Each nice step changes the weight by about a factor of 1.25.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 5, 2, 'How does EEVDF choose the next task?', '["Always the one that has waited the longest", "The one with the smallest pid", "Among tasks with non-negative lag, the one with the earliest virtual deadline", "A random one among the ready tasks"]', 2, 'Lag is the time owed minus the time received. Negative lag means the task has taken extra and will wait.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 5, 3, 'How can a responsive task get the CPU sooner without changing its time share?', '["Request a short slice via sched_setattr: its deadline comes earlier", "Raise its priority to nice -20", "Move to the SCHED_FIFO class", "Disable interrupts on the core"]', 0, 'A short slice moves the virtual deadline earlier, but the time share is determined by the weight, which has not changed.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 5, 4, 'What does sched_ext do?', '["Extends the kernel with drivers in Rust", "Increases the number of real-time priorities", "Moves the scheduler into a user process with no checks", "Lets you load a BPF scheduler into a running kernel; on failure the kernel falls back to EEVDF"]', 3, 'The program passes the verifier, attaches on the fly and rolls back safely. The class appeared in kernel 6.12.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 5, 5, 'How does the ordinary scheduler class divide the CPU among tasks?', '["Equally among all tasks regardless of nice", "In proportion to weights that depend on the nice value: bigger weight, bigger share", "High-priority tasks run until they finish", "In order of creation, one at a time"]', 1, 'The scheduler aims for fairness: each task has a weight, and the accumulated time is compared with what the weight entitles it to.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 5, 6, 'What did EEVDF bring compared with the earlier CFS?', '["A task can ask for a short slice and gets an earlier deadline, so latency can be requested directly", "It turned off fair time division", "It works on only one core", "It replaced the real-time classes"]', 0, 'EEVDF picks the task with the earliest deadline among those entitled to the CPU. A short slice means an early deadline, which means a quick response.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 5, 7, 'How does the SCHED_FIFO class differ from the ordinary one?', '["The task gets time quanta equally with the rest", "The task automatically lowers its own priority", "The task runs until it blocks or yields the CPU itself; ordinary tasks cannot preempt it", "The task runs only in kernel mode"]', 2, 'Real time hands out the CPU by strict priority. A forgotten infinite loop in such a task can freeze the machine.');
